  public function executeList()
  {
    $currentForm="transferencias_clientes/list";
    $this->verificaPrilegio($currentForm);
   
  	$c = new Criteria();
  	$parametros_consulta = "";
  	
	// ARCHIVO ACTUAL
    //$this->localizacion = $this->getRequestParameter('localizacionunidaddocumental_id');
	$c->add(ClTransferenciaPeer::CLDESTINOTRANSFERENCIA_ID, 1);	
	//$parametros_consulta .= "&localizacionunidaddocumental_id=".$this->localizacion;
	// ESTADO TRANSFERENCIA
	$estado_transferencia = $this->getRequestParameter('estado_transferencia');
	if($estado_transferencia != ""){
		$c->add(ClTransferenciaPeer::CLESTADOTRANSFERENCIA_ID, $estado_transferencia);	
		$parametros_consulta .= "&estado_transferencia=".$estado_transferencia;	
	}
	
	// ORIGEN TRANSFERENCIA
	$origen_transferencia = $this->getRequestParameter('origen_transferencia');
	if($origen_transferencia != ""){
		$c->add(ClTransferenciaPeer::CLORIGENTRANSFERENCIAID, $origen_transferencia);	
		$parametros_consulta .= "&origen_transferencia=".$origen_transferencia;	
	}
	
	// CONSULTA FECHA CREACION
	$fecha_creacion_inicial = $this->getRequestParameter('desde');
	$fecha_creacion_final = $this->getRequestParameter('hasta');
	if($fecha_creacion_inicial != ""){
		if($fecha_creacion_final == ""){
			$fecha_creacion_final = $fecha_creacion_inicial;
		}
		$c->add(ClTransferenciaPeer::FECHA_CREACION, $fecha_creacion_inicial.' 00:00:00', Criteria::GREATER_EQUAL);
		$c->addAnd(ClTransferenciaPeer::FECHA_CREACION, $fecha_creacion_final.' 23:59:59', Criteria::LESS_EQUAL);
		$parametros_consulta .= "&fecha_creacion_inicial=".str_replace("/","-",$fecha_creacion_inicial);
		$parametros_consulta .= "&fecha_creacion_final=".str_replace("/","-",$fecha_creacion_final);		
	}
	
	// CONSULTA INVENTARIADO POR
	$solicitado_por = $this->getRequestParameter('usuario_solicita');
	if($solicitado_por != ""){
		$c->addJoin(ClTransferenciaPeer::CLTRANSFERENCIA_ID, ClUsuarioTransferenciaPeer::CLTRANSFERENCIA_ID);
		$c->add(ClUsuarioTransferenciaPeer::USUARIO_ID, $solicitado_por);
		$c->add(ClUsuarioTransferenciaPeer::CLROLUSUARIOTRANSFERENCIA_ID, 1);
		$parametros_consulta .= "&usuario_solicita=".$solicitado_por;			
	}
	//cONSECUTIVO DE LA TRANSFERENCIA
	$num_trans = $this->getRequestParameter('numTransferencia');
	if($num_trans != ""){
		$c->add(ClTransferenciaPeer::CLTRANSFERENCIA_ID, $num_trans);
		//$c->add(UsuarioTransferenciaPeer::USUARIO_ID, $solicitado_por);
		//$c->add(UsuarioTransferenciaPeer::ROLUSUARIOTRANSFERENCIA_ID, 1);
		$parametros_consulta .= "&numTransferencia=".$solicitado_por;			
	}
	//Consulta por Codigo Del Cliente.
	$cod_cliente = $this->getRequestParameter('codigo_cliente');
	if($cod_cliente != ""){
		$c->addJoin(ClTransferenciaPeer::CLIENTE_ID,ClientePeer::CLIENTE_ID);
		$c->add(ClientePeer::CODIGO_CLIENTE, '%'.$cod_cliente.'%',Criteria::LIKE);		
		$parametros_consulta .= "&codigo_cliente=".$cod_cliente;			
	}
	$c->addDescendingOrderByColumn(ClTransferenciaPeer::CLTRANSFERENCIA_ID);
	
	$pager=new sfPropelPager('ClTransferencia',10);
	$pager->setCriteria($c);
	$pager->setPage($this->getRequestParameter('page',1));
	$pager->init();
	$this->pager=$pager;
	$this->filtros_consulta = $parametros_consulta;
  }

