      $cl_transferencia->setFechaAceptacion(date("Y-m-d G:i:s"));
    }
    $cl_transferencia->setFechaCreacion(date("Y-m-d G:i:s"));

    $cl_transferencia->save();
    
    // USUARIO TRANSFERENCIA    
