    public function executeTransferir()
    {
		if (!$this->getRequestParameter('cl_transferencia_id'))
    	{
      		$transferencia = new ClTransferencia();
    	}
    	else
    	{
      		$transferencia = ClTransferenciaPeer::retrieveByPk($this->getRequestParameter('cl_transferencia_id'));
      		$this->forward404Unless($transferencia);
    	}
    	$transferencia->setClestadotransferenciaId(2);
    	$transferencia->setFechaAceptacion(date('Y-m-d G:i:s'));
    	$transferencia->save();
    	
    	// USUARIO TRANSFERENCIA
		$usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$user_transfer = new ClUsuarioTransferencia();		
		$user_transfer->setClrolusuariotransferenciaId(2);
		$user_transfer->setCltransferenciaId($transferencia->getCltransferenciaId());
		$user_transfer->setUsuarioId($usuario_conectado);
		$user_transfer->save();
		
		// TRANSFERENCIA DESDE COMUNICACIONES
		if($transferencia->getClorigentransferenciaId() <= 3 || $transferencia->getClorigentransferenciaId() == 7){
			$contenido_documental = new ClienteContenido();
			$contenido_documental->setClienteId($transferencia->getClienteId());
			$contenido_documental->setVerificacioncontclienteId(2);
			$contenido_documental->setClEstadoContenidoId(1);
			$contenido_documental->setFechaCreacion(date('Y-m-d G:i:s'));
			$contenido_documental->setCreadoPorWeb(1);
			
			$c = new Criteria();
			$c->add(ClUsuarioTransferenciaPeer::CLROLUSUARIOTRANSFERENCIA_ID, 1);
			$c->add(ClUsuarioTransferenciaPeer::CLTRANSFERENCIA_ID, $transferencia->getCltransferenciaId());
			$usuario_solicita = ClUsuarioTransferenciaPeer::doSelectOne($c);
			
			
			$contenido_documental->setUsuarioId($usuario_solicita->getUsuarioId());
			
			
			switch($transferencia->getClorigentransferenciaId()){
				// INTERNA
				case 1:
					$parametro = ParametroPeer::retrieveByPK(19);
					$ruta = $parametro->getValortexto().$transferencia->getCominternaId();
					$cominterna = ComInternaPeer::retrieveByPK($transferencia->getCominternaId());
					$contenido_documental->setTipodocumentalId($transferencia->getTipodocumentalId());
					$contenido_documental->setDescripcion($cominterna->getRadicado()." - ".$cominterna->getReferencia());
					$contenido_documental->setFolios($cominterna->getFolios());
					$contenido_documental->setRuta($ruta);
					break;
				// ENTRANTE
				case 2:
					$parametro = ParametroPeer::retrieveByPK(20);
					$ruta = $parametro->getValortexto().$transferencia->getComrecibidaId();
					$comrecibida = ComRecibidaPeer::retrieveByPK($transferencia->getComrecibidaId());
					$contenido_documental->setTipodocumentalId($transferencia->getTipodocumentalId());
					$contenido_documental->setDescripcion($comrecibida->getRadicado()." - ".$comrecibida->getAsuntorecibida()->getDescripcion());
					$contenido_documental->setFolios($comrecibida->getFolios());
					$contenido_documental->setRuta($ruta);				
					break;
				// SALIENTE
				case 3:
					$parametro = ParametroPeer::retrieveByPK(21);
					$ruta = $parametro->getValortexto().$transferencia->getComenviadaId();
					$comenviada = ComEnviadaPeer::retrieveByPK($transferencia->getComenviadaId());
					$contenido_documental->setTipodocumentalId($transferencia->getTipodocumentalId());
					$contenido_documental->setDescripcion($comenviada->getRadicado()." - ".$comenviada->getAsunto());
					$contenido_documental->setFolios($comenviada->getFolios());
					$contenido_documental->setRuta($ruta);				
					break;
				//DOCUMENTACION TECNICA
				case 7:
					$parametro = ParametroPeer::retrieveByPK(44);
					$ruta = $parametro->getValortexto().$transferencia->getDocumentacionId();
					$documentacion = DocumentacionPeer::retrieveByPK($transferencia->getDocumentacionId());
					$contenido_documental->setTipodocumentalId($transferencia->getTipodocumentalId());
					$contenido_documental->setDescripcion($documentacion->getTitulo()." - ".$documentacion->getCodigoBarras());
					//$contenido_documental->setFolios($comenviada->getFolios());
					$contenido_documental->setRuta($ruta);				
					break;												
				///////////////////////////////////////////////////////////////////////																						
		     }
		  $contenido_documental->save();					
		}    			
		return $this->redirect($this->getRequest()->getScriptName().'/transferencias_clientes/show?cltransferencia_id='.$transferencia->getCltransferenciaId());
	}	
  
  public function executeRechazar()
  {
  	if (!$this->getRequestParameter('cltransferencia_id'))
    	{
      		$transferencia = new ClTransferencia();
    	}
    	else
    	{
      		$transferencia = ClTransferenciaPeer::retrieveByPk($this->getRequestParameter('cltransferencia_id'));
      		$this->forward404Unless($transferencia);
    	}
    	$transferencia->setClestadotransferenciaId(3);
    	$transferencia->setFechaAceptacion(date('Y-m-d G:i:s'));
    	$transferencia->save();
    	
    	// USUARIO TRANSFERENCIA
		$usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$user_transfer = new ClUsuarioTransferencia();		
		$user_transfer->setClrolusuariotransferenciaId(2);
		$user_transfer->setCltransferenciaId($transferencia->getCltransferenciaId());
		$user_transfer->setUsuarioId($usuario_conectado);
		$user_transfer->save();				
		
		return $this->redirect($this->getRequest()->getScriptName().'/transferencias_clientes/show?cltransferencia_id='.$transferencia->getCltransferenciaId());

  }
  
